export function Isr({
  pageTitle = "{{pageTitle}}",
  revalidateSeconds = {{revalidateSeconds}},
  stage = "{{stage}}",
  accent = "{{accent}}",
}) {
  const notes = {
    fresh: "Within the revalidate window \u2014 served as-is, no rebuild needed.",
    stale: <>Window expired &mdash; this stale copy is served <em>while</em> a rebuild is triggered.</>,
    regenerating: "Rebuilding in the background; the next visitor gets the fresh HTML.",
  };
  const highlighted = stage === "stale" || stage === "regenerating";
  return (
    <div role="img" aria-label={`${pageTitle}, ${stage}, revalidate every ${revalidateSeconds}s`} style={{ font: "12px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 16, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 10px", fontWeight: 700, display: "flex", justifyContent: "space-between", alignItems: "center", fontSize: 12 }}>{pageTitle} <span style={{ fontSize: 9, fontWeight: 400, color: "#24143099" }}>revalidate: {revalidateSeconds}s</span></p>
      <div style={{ padding: 12, borderRadius: 8, textAlign: "center", fontWeight: 600, marginBottom: 10, background: highlighted ? accent : "#24143010" }}>Served from static HTML</div>
      <p style={{ margin: 0, fontSize: 10, color: "#24143099" }}>{notes[stage]}</p>
    </div>
  );
}
